import data from './us-map.json' with { type: 'json' }

// State shapes for the home map, generated by packages/reference-data/src/us-map.ts from
// us-atlas (Census Bureau 1:10m, Albers USA). Imported as `@mfcd/shared/us-map` so only pages
// that draw the map carry the ~110 KB of paths.

export interface UsMapState {
  /** Two-letter postal code (`states.id`). */
  id: string
  /** Two-digit FIPS code, the join key to `states.fips`. */
  fips: string
  name: string
  /** SVG path in the `width` x `height` box. */
  d: string
  cx: number
  cy: number
}

export const usMap: { width: number; height: number; states: readonly UsMapState[] } = data
